--  DDL for View VW_CATALOGO_PRODUCTOS
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE VIEW "APP_OWNER"."VW_CATALOGO_PRODUCTOS" ("PRODUCTO_ID", "VARIANTE_ID", "SKU", "NOMBRE_MOSTRADO", "PRECIO_EFECTIVO", "URL_PORTADA", "ID_CATEGORIA", "ACTIVO") DEFAULT COLLATION "USING_NLS_COMP"  AS SELECT
        p.id AS producto_id,
        v.id AS variante_id,
        v.sku,
        COALESCE(v.nombre_es, p.nombre_es) AS nombre_mostrado,
        NVL(v.precio_sobrescrito, p.precio) AS precio_efectivo,
        (
            SELECT ma.url
            FROM medio_producto mp
            JOIN medio_archivo ma 
            ON mp.medio_id = ma.id
            WHERE mp.producto_id = p.id
              AND (mp.variante_id = v.id OR mp.variante_id IS NULL)
              AND mp.es_portada = 'S'
            ORDER BY mp.variante_id DESC
            FETCH FIRST 1 ROWS ONLY
        ) AS url_portada,
        
        p.id_categoria,
        v.activo
    FROM productos p
    JOIN variantes_producto v
    ON p.id = v.producto_id
    WHERE v.activo = 'S'
    
    UNION ALL

--  Producto base sin variantes
    SELECT
        p.id AS producto_id,
        NULL AS variante_id,
        NULL AS sku,
        p.nombre_es AS nombre_mostrado,
        p.precio AS precio_efectivo,
        (
            SELECT ma.url
            FROM medio_producto mp
            JOIN medio_archivo ma 
            ON mp.medio_id = ma.id
            WHERE mp.producto_id = p.id
              AND mp.variante_id IS NULL
              AND mp.es_portada = 'S'
            FETCH FIRST 1 ROWS ONLY
        ) AS url_portada,
        p.id_categoria,
        'S' AS activo
    FROM productos p
    WHERE NOT EXISTS(SELECT 1 FROM variantes_producto v WHERE v.producto_id = p.id)
--------------------------------------------------------
--  DDL for View VW_DESEMPENO_CUPONES
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE VIEW "APP_OWNER"."VW_DESEMPENO_CUPONES" ("CUPON_ID", "CODIGO", "USOS_TOTALES", "VENTAS_GENERADAS", "DESCUENTO_PROMEDIO_TEORICO") DEFAULT COLLATION "USING_NLS_COMP"  AS WITH subtotales AS (
  SELECT dp.pedido_id,
         SUM(dp.cantidad * dp.precio_unitario) AS subtotal
  FROM   detalle_pedidos dp
  GROUP  BY dp.pedido_id
)
SELECT
  c.id                               AS cupon_id,
  c.codigo                           AS codigo,
  COUNT(r.pedido_id)                 AS usos_totales,
  NVL(SUM(p.total_precio), 0)        AS ventas_generadas,
  NVL(ROUND(AVG(
    CASE
      WHEN c.tipo_descuento = 'monto'
        THEN LEAST(NVL(s.subtotal,0), c.valor_descuento)
      WHEN c.tipo_descuento = 'porcentaje'
        THEN ROUND(NVL(s.subtotal,0) * (c.valor_descuento/100), 2)
      ELSE 0
    END
  ), 2), 0)                          AS descuento_promedio_teorico
FROM   cupones c
LEFT   JOIN redenciones_cupones r ON r.cupon_id = c.id
LEFT   JOIN pedidos p             ON p.id = r.pedido_id
LEFT   JOIN subtotales s          ON s.pedido_id = r.pedido_id
GROUP  BY c.id, c.codigo
--------------------------------------------------------
--  DDL for View VW_DETALLE_CARRITO
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE VIEW "APP_OWNER"."VW_DETALLE_CARRITO" ("CARRITO_ID", "PERFIL_ID", "ESTADO", "CUPON_ID", "CANTIDAD_ITEMS", "SUBTOTAL_ESTIMADO", "DESCUENTO_ESTIMADO", "TOTAL_ESTIMADO") DEFAULT COLLATION "USING_NLS_COMP"  AS WITH 
-- 1. Agregar los items y calcular el subtotal
carrito_subtotales AS (
  SELECT
    ci.carrito_id,
    COALESCE(SUM(ci.cantidad), 0) AS cantidad_items,
    COALESCE(SUM(ci.cantidad * ci.precio_unitario_observado), 0) AS subtotal_estimado
  FROM
    cart_items ci
  GROUP BY
    ci.carrito_id
),
-- 2. Unir carritos con subtotales y la data del cupón
carrito_base AS (
  SELECT
    c.id AS carrito_id,
    c.perfil_id,
    c.estado,
    c.cupon_id,
    COALESCE(cs.cantidad_items, 0) AS cantidad_items,
    COALESCE(cs.subtotal_estimado, 0) AS subtotal_estimado,
    -- Columnas del cupón que necesita el SELECT final
    cup.tipo_descuento,
    cup.valor_descuento,
    cup.subtotal_minimo
  FROM
    carritos c
  LEFT JOIN
    carrito_subtotales cs ON c.id = cs.carrito_id
  LEFT JOIN
    cupones cup ON c.cupon_id = cup.id
)
-- 3. Calcular descuento estimado y total
SELECT
  cb.carrito_id,
  cb.perfil_id,
  cb.estado,
  cb.cupon_id,
  cb.cantidad_items,
  cb.subtotal_estimado,
  
  -- Lógica de descuento 
  (CASE
    WHEN cb.cupon_id IS NULL OR cb.subtotal_estimado = 0 THEN 0
    WHEN cb.subtotal_minimo IS NOT NULL AND cb.subtotal_estimado < cb.subtotal_minimo THEN 0 
    WHEN cb.tipo_descuento = 'monto' 
      THEN LEAST(cb.subtotal_estimado, cb.valor_descuento)
    WHEN cb.tipo_descuento = 'porcentaje' 
      THEN ROUND(cb.subtotal_estimado * (cb.valor_descuento / 100), 2)
    ELSE 0
  END) AS descuento_estimado,

  -- Total Estimado (Subtotal - Descuento)
  (cb.subtotal_estimado - 
    (CASE
      WHEN cb.cupon_id IS NULL OR cb.subtotal_estimado = 0 THEN 0
      WHEN cb.subtotal_minimo IS NOT NULL AND cb.subtotal_estimado < cb.subtotal_minimo THEN 0 
      WHEN cb.tipo_descuento = 'monto' 
        THEN LEAST(cb.subtotal_estimado, cb.valor_descuento)
      WHEN cb.tipo_descuento = 'porcentaje' 
        THEN ROUND(cb.subtotal_estimado * (cb.valor_descuento / 100), 2)
      ELSE 0
    END)
  ) AS total_estimado
FROM
  carrito_base cb
--------------------------------------------------------
--  DDL for View VW_DETALLE_PEDIDO
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE VIEW "APP_OWNER"."VW_DETALLE_PEDIDO" ("PEDIDO_ID", "PEDIDO_FECHA", "PEDIDO_TOTAL_PRECIO", "PEDIDO_PRODUCTO_ID", "PEDIDO_PRODUCTO_NOMBRE", "PEDIDO_VARIANTE_ID", "PEDIDO_SKU", "PEDIDO_CANTIDAD", "PEDIDO_PRECIO_UNITARIO", "PEDIDO_TOTAL_LINEA", "FACTURA_ID", "FACTURA_NUMERO", "FACTURA_EMITIDO_EN", "FACTURA_MONEDA", "FACTURA_SUBTOTAL", "FACTURA_DESCUENTO_TOTAL", "FACTURA_IMPUESTO_TOTAL", "FACTURA_TOTAL_GENERAL", "FACTURA_LINEA", "FACTURA_CANTIDAD", "FACTURA_PRECIO_UNITARIO", "FACTURA_TOTAL_LINEA") DEFAULT COLLATION "USING_NLS_COMP"  AS SELECT
  -- Pedido
  p.id                               AS pedido_id,
  p.fecha_pedido                     AS pedido_fecha,
  p.total_precio                     AS pedido_total_precio,
  /* Si tienes columna de estado en PEDIDOS, descomenta:
  p.estado                           AS pedido_estado,
  */

  -- Detalle de pedido
  dp.producto_id                     AS pedido_producto_id,
  pr.nombre_es                       AS pedido_producto_nombre,
  dp.variante_id                     AS pedido_variante_id,
  vp.sku                             AS pedido_sku,
  dp.cantidad                        AS pedido_cantidad,
  dp.precio_unitario                 AS pedido_precio_unitario,
  ROUND(dp.cantidad * dp.precio_unitario, 2) AS pedido_total_linea,

  -- Factura (LEFT JOIN, puede no existir aún)
  f.id                               AS factura_id,
  f.numero                           AS factura_numero,
  f.emitido_en                       AS factura_emitido_en,
  f.moneda                           AS factura_moneda,
  f.subtotal                         AS factura_subtotal,
  f.descuento_total                  AS factura_descuento_total,
  f.impuesto_total                   AS factura_impuesto_total,
  f.total_general                    AS factura_total_general,

  -- Línea de factura (si existe; mapeo por producto/variante)
  fi.linea                           AS factura_linea,
  fi.cantidad                        AS factura_cantidad,
  fi.precio_unitario                 AS factura_precio_unitario,
  fi.total_linea                     AS factura_total_linea

  /* Si manejas cupones/redenciones ligados al pedido, puedes exponerlos aquí:
  , cr.cupon_id                       AS cupon_id
  , c.codigo                          AS cupon_codigo
  , cr.descuento_aplicado             AS cupon_descuento
  */
FROM APP_OWNER.PEDIDOS              p
JOIN APP_OWNER.DETALLE_PEDIDOS      dp  ON dp.pedido_id = p.id
LEFT JOIN APP_OWNER.PRODUCTOS       pr  ON pr.id = dp.producto_id
LEFT JOIN APP_OWNER.VARIANTES_PRODUCTO vp ON vp.id = dp.variante_id

LEFT JOIN APP_OWNER.FACTURAS        f   ON f.pedido_id = p.id
LEFT JOIN APP_OWNER.FACTURA_ITEMS   fi
       ON fi.factura_id = f.id
      AND fi.producto_id = dp.producto_id
      AND ( (fi.variante_id IS NULL AND dp.variante_id IS NULL)
            OR fi.variante_id = dp.variante_id )
--------------------------------------------------------
--  DDL for View VW_METRICAS_CANCELACION
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE VIEW "APP_OWNER"."VW_METRICAS_CANCELACION" ("CODIGO_MOTIVO", "FECHA_CANCELACION", "TOTAL_CANCELACIONES", "TOTAL_ITEMS_CANCELADOS") DEFAULT COLLATION "USING_NLS_COMP"  AS SELECT
  d.codigo_motivo,
  TRUNC(d.creado_en) AS fecha_cancelacion,
  COUNT(DISTINCT d.id) AS total_cancelaciones,
  SUM(di.cantidad) AS total_items_cancelados
FROM devoluciones d
JOIN devolucion_items di ON d.id = di.devolucion_id
WHERE d.estado = 'cancelado'
GROUP BY
  d.codigo_motivo,
  TRUNC(d.creado_en)
--------------------------------------------------------
--  DDL for View VW_SNAPSHOT_INVENTARIO
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE VIEW "APP_OWNER"."VW_SNAPSHOT_INVENTARIO" ("VARIANTE_PRODUCTO_ID", "PRODUCTO_ID", "SKU", "VARIANTE_NOMBRE", "EXISTENCIA", "RESERVADO", "DISPONIBLE", "ULTIMO_MOVIMIENTO_EN") DEFAULT COLLATION "USING_NLS_COMP"  AS SELECT
  vp.id AS variante_producto_id,
  vp.producto_id,
  vp.sku,
  vp.nombre_es AS variante_nombre,
  s.existencia,
  s.reservado,
  (s.existencia - s.reservado) AS disponible,
  s.actualizado_en AS ultimo_movimiento_en
FROM 
  saldos_inventario s
JOIN 
  variantes_producto vp ON s.variante_producto_id = vp.id
WHERE
  vp.activo = 'S'
--------------------------------------------------------
--  DDL for View VW_VENTAS_DIARIAS
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE VIEW "APP_OWNER"."VW_VENTAS_DIARIAS" ("FECHA", "CANT_FACTURAS", "UNIDADES", "SUBTOTAL", "DESCUENTO_TOTAL", "IMPUESTO_TOTAL", "TOTAL_GENERAL") DEFAULT COLLATION "USING_NLS_COMP"  AS WITH facturas_base AS (
  SELECT
    TRUNC(CAST((f.emitido_en AT LOCAL) AS DATE)) AS fecha_local,
    f.id         AS factura_id,
    f.subtotal   AS subtotal,
    f.descuento_total AS descuento_total,
    f.impuesto_total  AS impuesto_total,
    f.total_general   AS total_general
  FROM APP_OWNER.FACTURAS f
)
SELECT
  fb.fecha_local                                   AS fecha,
  COUNT(DISTINCT fb.factura_id)                    AS cant_facturas,
  (
    SELECT NVL(SUM(fi.cantidad), 0)
    FROM APP_OWNER.FACTURA_ITEMS fi
    JOIN APP_OWNER.FACTURAS f2 ON f2.id = fi.factura_id
    WHERE TRUNC(CAST((f2.emitido_en AT LOCAL) AS DATE)) = fb.fecha_local
  )                                                AS unidades,
  ROUND(SUM(fb.subtotal),        2)                AS subtotal,
  ROUND(SUM(fb.descuento_total), 2)                AS descuento_total,
  ROUND(SUM(fb.impuesto_total),  2)                AS impuesto_total,
  ROUND(SUM(fb.total_general),   2)                AS total_general
FROM facturas_base fb
GROUP BY fb.fecha_local
